## TL;DR  
MapLibre Android does not have a `addProtocol()` helper, but the SDK lets you plug-in **your own network layer**.  
You can either  

1. **Provide a custom `HttpRequestHandler`** (the API that MapLibre Native uses internally), or  
2. **Supply an `OkHttpClient` with an interceptor** that recognises the `vault://` scheme, decrypts the tile and returns a synthetic HTTP-200 response.

Both approaches give you exactly the same hook that `maplibregl.addProtocol()` gives on the web – every request that the style JSON makes (including vector-tile requests) passes through your code, where you can turn the encrypted blob into the raw PBF bytes.

Below is a complete, ready-to-copy Kotlin example that uses the **interceptor** method (the most common way with the current MapLibre-Android 10.x+ releases).  
If you prefer the older `HttpRequestHandler` interface, the same logic can be placed there – the code is shown after the interceptor example.

---

## 1️⃣  Add a custom `OkHttpClient` with an interceptor

```kotlin
import android.content.Context
import android.net.Uri
import com.mapbox.mapboxsdk.Mapbox
import com.mapbox.mapboxsdk.maps.Style
import com.mapbox.mapboxsdk.maps.MapView
import com.mapbox.mapboxsdk.maps.MapboxMap
import com.mapbox.mapboxsdk.MapboxOptions
import okhttp3.*
import okio.Buffer
import java.io.IOException

// ---------------------------------------------------------------------------
// 1️⃣  Interceptor that knows how to handle "vault://" URLs
// ---------------------------------------------------------------------------
class VaultTileInterceptor(
    private val context: Context,
    private val vault: TileVault   // your own class that knows how to read & decrypt
) : Interceptor {

    @Throws(IOException::class)
    override fun intercept(chain: Interceptor.Chain): Response {
        val request = chain.request()
        val url = request.url

        // -------------------------------------------------------------------
        // Only intercept our custom scheme – everything else falls back to
        // the normal network stack.
        // -------------------------------------------------------------------
        if (url.scheme != "vault") {
            return chain.proceed(request)          // normal HTTP/HTTPS request
        }

        // -------------------------------------------------------------------
        // Parse z / x / y from the URL: vault://tiles/{z}/{x}/{y}.pbf
        // -------------------------------------------------------------------
        // Example URL: vault://tiles/12/3456/7890.pbf
        val pathSegments = url.pathSegments
        if (pathSegments.size < 3) {
            return makeErrorResponse(request, 400, "Invalid vault tile URL")
        }

        val z = pathSegments[0].toInt()
        val x = pathSegments[1].toInt()
        val y = pathSegments[2].toInt()

        // -------------------------------------------------------------------
        // Decrypt the tile from your encrypted blob.
        // This method must return the raw PBF bytes (or throw if not found).
        // -------------------------------------------------------------------
        val tileBytes: ByteArray = try {
            vault.decryptTile(z, x, y)   // <-- implement this yourself
        } catch (e: Exception) {
            return makeErrorResponse(request, 404, "Tile not found")
        }

        // -------------------------------------------------------------------
        // Build a synthetic HTTP-200 response that MapLibre will treat as a
        // normal tile payload.
        // -------------------------------------------------------------------
        val body = ResponseBody.create(null, tileBytes)

        return Response.Builder()
            .request(request)
            .protocol(Protocol.HTTP_1_1)
            .code(200)                     // success
            .message("OK")
            .body(body)
            .addHeader("Content-Type", "application/x-protobuf")
            .build()
    }

    private fun makeErrorResponse(request: Request, code: Int, message: String): Response {
        val body = ResponseBody.create(null, message)
        return Response.Builder()
            .request(request)
            .protocol(Protocol.HTTP_1_1)
            .code(code)
            .message(message)
            .body(body)
            .build()
    }
}

// ---------------------------------------------------------------------------
// 2️⃣  Wire the interceptor into MapLibre's HTTP client
// ---------------------------------------------------------------------------
fun initMapLibre(context: Context) {
    // 1️⃣ Create the OkHttp client that contains our interceptor
    val okHttpClient = OkHttpClient.Builder()
        .addInterceptor(VaultTileInterceptor(context, TileVault(context)))
        .build()

    // 2️⃣ Build MapLibreOptions that tell the SDK to use *our* client
    val mapLibreOptions = MapboxOptions.Builder()
        .httpClient(okHttpClient)          // <-- this is the key line
        .build()

    // 3️⃣ Initialise the SDK (only once, usually in Application.onCreate())
    Mapbox.getInstance(context, mapLibreOptions)
}

// ---------------------------------------------------------------------------
// 3️⃣  Use the SDK as usual – the style can now reference vault:// URLs
// ---------------------------------------------------------------------------
class MyMapActivity : AppCompatActivity() {

    private lateinit var mapView: MapView

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        // Initialise MapLibre *before* inflating any MapView
        initMapLibre(this)

        setContentView(R.layout.activity_map)
        mapView = findViewById(R.id.mapView)
        mapView.onCreate(savedInstanceState)

        mapView.getMapAsync { mapboxMap: MapboxMap ->
            // Example style JSON that points to the encrypted tiles
            val styleJson = """
                {
                  "version": 8,
                  "sources": {
                    "my-vault-tiles": {
                      "type": "vector",
                      "tiles": ["vault://tiles/{z}/{x}/{y}.pbf"],
                      "minzoom": 0,
                      "maxzoom": 14
                    }
                  },
                  "layers": [
                    {
                      "id": "water",
                      "type": "fill",
                      "source": "my-vault-tiles",
                      "source-layer": "water",
                      "paint": { "fill-color": "#a0c8f0" }
                    }
                  ]
                }
            """.trimIndent()

            mapboxMap.setStyle(Style.Builder().fromJson(styleJson))
        }
    }

    // … forward the usual lifecycle calls to mapView …
}
```

### What the code does

| Step | What happens |
|------|--------------|
| **Interceptor** (`VaultTileInterceptor`) | Every request that the SDK creates is examined. If the URL scheme is `vault`, we parse the `{z}/{x}/{y}` placeholders, ask our own `TileVault` class to read the encrypted blob and decrypt it, then hand the raw bytes back as an `OkHttp` `Response`. |
| **OkHttp client** | The interceptor is added to a custom `OkHttpClient`. |
| **MapLibreOptions** | `MapboxOptions.Builder().httpClient(customClient)` tells the native SDK to use *our* client for **all** network traffic (tiles, glyphs, sprites, etc.). |
| **Style JSON** | The style can now contain `"tiles": ["vault://tiles/{z}/{x}/{y}.pbf"]`. The SDK will request those URLs, the interceptor will catch them, decrypt the data and feed it back to the renderer. |

